   250→      // Create a new timer with the same timeout duration
   251→      pending.timer = setTimeout(() => {
   252→        this.pending.delete(pending.id);
   253→        pending.reject(
   254→          new Error(
   255→            `Request ${pending.id} timed out after ${pending.timeoutMs}ms (method: ${pending.method})`,
   256→          ),
   257→        );
   258→      }, pending.timeoutMs);
   259→    }
   260→  }
   261→
   262→  /**
   263→   * Send a JSON-RPC message
   264→   */
   265→  private send(message: JsonRpcMessage): void {
   266→    try {
   267→      const json = JSON.stringify(message);
   268→      this.stdout.write(`${json}\n`);
   269→    } catch (err) {
   270→      console.error(`Error sending message: ${err}`);
   271→    }
   272→  }
   273→
   274→  /**
   275→   * Handle incoming data from stdin
   276→   */
   277→  private handleData(chunk: string): void {
   278→    this.buffer += chunk;
   279→
   280→    // Process complete lines
   281→    let newlineIndex = this.buffer.indexOf("\n");
   282→    while (newlineIndex !== -1) {
   283→      const line = this.buffer.slice(0, newlineIndex);
   284→      this.buffer = this.buffer.slice(newlineIndex + 1);
   285→
   286→      if (line.trim()) {
   287→        this.processLine(line);
   288→      }
   289→      newlineIndex = this.buffer.indexOf("\n");
   290→    }
   291→  }
   292→
   293→  /**
   294→   * Process a complete line of input
