   339→   */
   340→  private handleResponse(response: JsonRpcResponse): void {
   341→    const pending = this.pending.get(response.id);
   342→    if (pending) {
   343→      clearTimeout(pending.timer);
   344→      this.pending.delete(response.id);
   345→      pending.resolve(response.result);
