   363→      this.emit("error", error.error);
   364→      return;
   365→    }
   366→
   367→    const pending = this.pending.get(error.id);
   368→    if (pending) {
   369→      clearTimeout(pending.timer);
   370→      this.pending.delete(error.id);
   371→
   372→      // Skip logging for expected "Method not found" errors on optional methods
   373→      const isSilentMethodNotFound =
   374→        pending.options?.silentMethodNotFound &&
   375→        error.error.code === METHOD_NOT_FOUND;
   376→
   377→      if (!isSilentMethodNotFound) {
   378→        console.error(
   379→          `JSON-RPC error: ${error.error.message} (code: ${error.error.code}, method: ${pending.method})`,
   380→        );
   381→      }
   382→
   383→      const err = Object.assign(new Error(error.error.message), {
   384→        code: error.error.code,
   385→        data: error.error.data,
   386→      });
   387→      pending.reject(err);
   388→    } else {
   389→      // Unexpected error response
   390→      console.error(
   391→        `Warning: Received error for unknown request ID: ${error.id}`,
   392→      );
   393→    }
   394→  }
   395→
   396→  /**
   397→   * Handle stdin end
   398→   */
   399→  private handleEnd(): void {
   400→    this.close();
   401→  }
   402→
   403→  /**
   404→   * Handle stdin error
   405→   */
   406→  private handleError(err: Error): void {
   407→    console.error(`Stdin error: ${err.message}`);
