      const closeAndCheck = new Promise<void>((resolve) => {
        setTimeout(() => {
          client.close();
          resolve();
        }, 10);
      });

      await closeAndCheck;
      await expect(sessionPromise).rejects.toThrow('JsonRpcFraming closed');
