          const request = JSON.parse(chunk.toString());
          requestId = request.id;
          resolve();
        });
      });

      // Start first prompt (don't await)
      const firstPrompt = client.prompt({
        sessionId: 'session-123',
        prompt: [{ type: 'text', text: 'Hello' }],
