    it('should throw on operations after close', async () => {
      const initPromise = client.initialize();
      await respondToNext({ protocolVersion: 1, agentCapabilities: {} });
      await initPromise;

      client.close();

      await expect(client.newSession({ cwd: '/' })).rejects.toThrow('closed');
